n  // SQLite 对 Json 默认值支持不完整（无 JSONB），默认值在应用层代码中传入空数组\n  attachments Json\n\n  // 软删（保留数据但不在列表显示，未来可恢复）\n  deletedAt DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  // 关联\n  messages ChatMessage[]\n  // 注意：Favorite 仅收藏单条消息（连 ChatMessage，不连 ChatSession）\n  // 如需收藏整个会话，后续再加 chatSessionId 到 Favorite 表\n  shares   SharedSession[]\n\n  @@index([userId, createdAt]) // 历史列表按 userId + 创建时间倒序\n}\n\n// --------------------------------------------------------------\n// 3. ChatMessage 单条消息（用户 / AI）\n// --------------------------------------------------------------\nmodel ChatMessage {\n  id        String      @id @default(cuid())\n  sessionId String\n  session   ChatSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  role            String // 'user' | 'assistant'\n  content         String // 正文 Markdown\n  thinkingContent String? // R1 推理模型的思考链（reasoning_content），兼容后续\n\n  // sources JSON：AI 回答引用的 8~15 条参考来源（来自 web search + 平台引用）\n  // 对应 ChatSource[]：{ id, origin: 'web'|'platform', title, url, snippet, domain, citedCount? }\n  // SQLite JSON 默认值不写 schema，应用层传入空数组\n  sources Json\n\n  createdAt DateTime @default(now())\n\n  // 关联\n  favorites Favorite[]\n\n  @@index([sessionId, createdAt]) // 按会话 + 时间顺序拉消息\n}\n\n// --------------------------------------------------------------\n// 4. ResearchSession Deep Research 研究报告会话（mock done 写一次）\n// --------------------------------------------------------------\nmodel ResearchSession {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  title  String // 研究题目（入口展示）\n  scope  String? // 可选范围描述（深度/广度）\n  status String  @default(\"done\") // 'running' | 'done' | 'failed'；当前 mock 模式仅 done\n\n  // 报告产物 JSON：sections + report + sources（与当前 mock 播放器结构一致，便于 live 模式复用）\n  // SQLite JSON 默认值不写 schema，应用层传入 [] / {}\n  sections Json // DRPlanSection[]：4 节大纲\n  sources  Json // 参考来源\n  report   Json // 报告正文 + 结构 + references\n\n  deletedAt DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@index([userId, createdAt])\n}\n\n// --------------------------------------------------------------\n// 5. Favorite 用户收藏（⭐按钮写入）\n// --------------------------------------------------------------\nmodel Favorite {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  messageId String\n  message   ChatMessage @relation(fields: [messageId], references: [id], onDelete: Cascade)\n\n  note String? // 用户备注（后续扩展）\n\n  createdAt DateTime @default(now())\n\n  // 联合唯一约束：同一人同一条消息只能收藏一次\n  @@unique([userId, messageId])\n  @@index([userId, createdAt])\n}\n\n// --------------------------------------------------------------\n// 6. SharedSession 只读分享链接（12 位 token）\n// --------------------------------------------------------------\nmodel SharedSession {\n  id        String      @id @default(cuid())\n  sessionId String\n  session   ChatSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  token     String    @unique // 12 位 base62，/share/{token} 路由匹配\n  createdAt DateTime  @default(now())\n  expiresAt DateTime? // 可选：30 天后过期（null = 永不过期，原型默认永不过期）\n\n  @@index([token])\n}\n\n// --------------------------------------------------------------\n// 7. PasswordResetToken 找回密码令牌\n//    （对比选型 §1.1 方案 A；JWT 方案可省一张表，但原型用表更直观）\n// --------------------------------------------------------------\nmodel PasswordResetToken {\n  id        String    @id @default(cuid())\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String    @unique // JWT 或随机串；原型用 randomUUID\n  expiresAt DateTime // 一般 1 小时内有效\n  usedAt    DateTime? // 已使用标记\n  createdAt DateTime  @default(now())\n\n  @@index([token])\n}\n",
